        elif (p % 8 == 3 or p % 8 == 5):
            return -pow(a, (p - 1) // 2, p)

def fast_power(base, exp, mod):
    result = 1
    base = base % mod
    while exp > 0:
        if (exp % 2) == 1:  # If exp is odd, multiply base with result
